import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"Choose an install path","description":"Official binaries embed the admin UI and are named by content hash, so pick them by prefix; the one-click script only prepares PostgreSQL on Linux, Windows is manual-only.","frontmatter":{"title":"Choose an install path","description":"Official binaries embed the admin UI and are named by content hash, so pick them by prefix; the one-click script only prepares PostgreSQL on Linux, Windows is manual-only."},"headers":[],"relativePath":"en/guide/install/index.md","filePath":"en/guide/install/index.md","lastUpdated":1790057721000}`),a={name:`en/guide/install/index.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="choose-an-install-path" tabindex="-1">Choose an install path <a class="header-anchor" href="#choose-an-install-path" aria-label="Permalink to “Choose an install path”">​</a></h1><p>The primary install path is a <strong>GitHub Releases executable</strong> or the Docker image <code>kirizuofficial/kirivers</code>. You do not need Node.js or Go, and you do not compile or copy admin UI files. Official executables already embed the admin UI.</p><p>Follow the current <a href="https://github.com/Kirizu-Official/KiriVers/releases" target="_blank" rel="noreferrer">GitHub Releases</a> and Docker Hub tags. Do not use guessed download URLs that 404.</p><h2 id="matrix" tabindex="-1">Matrix <a class="header-anchor" href="#matrix" aria-label="Permalink to “Matrix”">​</a></h2><table tabindex="0"><thead><tr><th>Environment</th><th>Recommendation</th></tr></thead><tbody><tr><td>Linux (Debian/Ubuntu: apt; RHEL/CentOS/Fedora: yum or dnf)</td><td>Optionally run the <a href="/en/guide/install/one-click">one-click script</a> to install PostgreSQL (Redis optional), then download the program per <a href="/en/guide/install/manual">manual install</a></td></tr><tr><td>Windows</td><td><strong>Do not</strong> run the script. Follow manual install: the official installer for PostgreSQL, Redis optional or the memory cache, then the <code>.exe</code></td></tr><tr><td>macOS and any Linux without apt/yum/dnf</td><td>The script exits. Use manual install, or <a href="/en/guide/install/docker">Docker</a></td></tr><tr><td>Docker already available</td><td><a href="/en/guide/install/docker">Docker</a> or <a href="/en/guide/install/compose">Compose</a> to run the program and the database together</td></tr></tbody></table><h2 id="releases-files" tabindex="-1">Picking a Release asset <a class="header-anchor" href="#releases-files" aria-label="Permalink to “Picking a Release asset”">​</a></h2><p>Open <a href="https://github.com/Kirizu-Official/KiriVers/releases" target="_blank" rel="noreferrer">https://github.com/Kirizu-Official/KiriVers/releases</a> and pick the archive by <strong>prefix</strong>: <code>KiriVers-&lt;OS&gt;-&lt;Arch&gt;-&lt;hash&gt;.zip</code>. The trailing six characters are the first six hex digits of the SHA-256 of the binary inside, so every filename changes on every release — recognise the prefix, do not bookmark a specific link. Extracting gives you an executable named <code>kirivers-&lt;os&gt;-&lt;arch&gt;</code> (<code>.exe</code> on Windows).</p><table tabindex="0"><thead><tr><th>Your system</th><th>Typical CPU</th><th>Download prefix</th></tr></thead><tbody><tr><td>Windows</td><td>x64</td><td><code>KiriVers-Windows-x86_64-</code></td></tr><tr><td>Windows</td><td>32-bit x86</td><td><code>KiriVers-Windows-x86-</code></td></tr><tr><td>Windows</td><td>Arm</td><td><code>KiriVers-Windows-arm64-</code></td></tr><tr><td>Linux</td><td>x86_64</td><td><code>KiriVers-Linux-x86_64-</code></td></tr><tr><td>Linux</td><td>aarch64</td><td><code>KiriVers-Linux-arm64-</code></td></tr><tr><td>Linux</td><td>32-bit x86</td><td><code>KiriVers-Linux-x86-</code></td></tr><tr><td>Linux</td><td>ARMv7 (Raspberry Pi 2/3 and similar)</td><td><code>KiriVers-Linux-armv7-</code></td></tr><tr><td>Linux</td><td>RISC-V 64</td><td><code>KiriVers-Linux-riscv64-</code></td></tr><tr><td>macOS</td><td>Intel</td><td><code>KiriVers-macOS-x86_64-</code></td></tr><tr><td>macOS</td><td>Apple Silicon</td><td><code>KiriVers-macOS-arm64-</code></td></tr></tbody></table><p>Each release also carries <code>SHA256SUMS.txt</code> (the uploaded files are verifiable directly with <code>sha256sum -c</code>) and <code>frontend-dist.zip</code> (admin console static files; official binaries already embed them, so you normally do not need it).</p><p>On Windows, check Task Manager → Performance or System Information for x64 vs ARM. On Linux / macOS, run <code>uname -m</code> (<code>x86_64</code>, <code>aarch64</code> / <code>arm64</code>).</p><div class="warning custom-block"><p class="custom-block-title">The three Linux libc flavours</p><p><code>x86_64</code> and <code>arm64</code> are <strong>musl</strong> builds (they run on Alpine). <code>x86</code>, <code>armv7</code> and <code>riscv64</code> are <strong>glibc cross builds</strong> and require glibc ≥ 2.39 on the target (Ubuntu 24.04 generation); armv7 additionally needs hard-float. On older systems use <a href="/en/guide/install/docker">Docker</a> or build from source.</p></div><p>Next: <a href="/en/guide/install/one-click">one-click dependencies</a> (Linux only) or <a href="/en/guide/install/manual">manual install</a>.</p>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};